def merge_intervals(intervals):
    if not intervals:
        return []

    # Create a copy of the intervals to avoid mutating the input
    intervals = [list(interval) for interval in intervals]
    # Sort intervals based on the start value
    intervals.sort(key=lambda x: x[0])

    merged = []
    for interval in intervals:
        if not merged:
            merged.append(interval)
        else:
            last = merged[-1]
            if interval[0] <= last[1]:
                # Overlapping or touching intervals, merge them
                last[1] = max(last[1], interval[1])
            else:
                merged.append(interval)

    return merged

from collections import defaultdict, deque

def toposort(nodes, edges):
    in_degree = {node: 0 for node in nodes}
    adj = defaultdict(list)

    for src, dst in edges:
        if src == dst:
            raise ValueError("Self loop detected")
        adj[src].append(dst)
        in_degree[dst] += 1

    queue = deque(sorted(node for node in nodes if in_degree[node] == 0))
    result = []

    while queue:
        node = queue.popleft()
        result.append(node)

        for neighbor in sorted(adj[node]):
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError
    batches = []
    current_batch = []
    current_weight = 0
    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError
        if current_weight + weight > limit:
            if current_batch:
                batches.append(current_batch)
            current_batch = [name]
            current_weight = weight
        else:
            current_batch.append(name)
            current_weight += weight
    if current_batch:
        batches.append(current_batch)
    return batches

import re

def parse_env(text):
    env_dict = {}
    key_pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    line_pattern = re.compile(r'^([^=]+)=(.*)$')

    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        match = line_pattern.match(line)
        if not match:
            raise ValueError(f"Invalid line: {line}")

        key, value = match.groups()
        key = key.strip()
        value = value.strip()

        if not key_pattern.match(key):
            raise ValueError(f"Invalid key: {key}")

        if (value.startswith('"') and value.endswith('"')) or (value.startswith("'") and value.endswith("'")):
            value = value[1:-1]

        env_dict[key] = value

    return env_dict

