def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("Arguments must be nonnegative")
    if attempt == 0:
        return min(cap, base)
    # Use logarithms to avoid constructing huge integers
    import math
    if base == 0:
        return min(cap, 0.0)
    log_term = math.log2(base) + attempt
    if log_term > 1024:  # Prevent overflow in exponentiation
        return cap
    return min(cap, base * (2 ** attempt))

def fifo_admit(active, queued, budget, slots):
    # Validate inputs
    if not all(isinstance(x, int) and x > 0 for x in queued):
        raise ValueError("All queued reservations must be positive integers")
    if any(x > budget for x in queued):
        raise ValueError("A queued reservation exceeds the whole budget")

    # Compute current usage
    active_sum = sum(active)
    active_len = len(active)

    admitted = []
    remaining = []

    for req in queued:
        # Check if we can admit this request
        if active_len < slots and active_sum + req <= budget:
            admitted.append(req)
            active_sum += req
            active_len += 1
        else:
            remaining.append(req)

    return (admitted, remaining)
